	mod, err := caddy.GetModule("http.matchers.client_ip")
	if err != nil {
		return d.Err(err.Error())
	}
	constructor := mod.New
	if constructor == nil {
		return d.Err("client_ip matcher module is missing a constructor")
	}
	instance := constructor()
	if instance == nil {
		return d.Err("client_ip matcher module constructor returned nil")
	}
	_, ok := instance.(caddyfile.Unmarshaler)
	if !ok {
		return d.Err("client_ip matcher module is not a Caddyfile unmarshaler")
	}

	d.Next() // consume matcher name
	for d.NextArg() {
		raw := d.Val()
		if raw == "private_ranges" {
			privateRanges := PrivateRangesCIDR()
			for _, cidr := range privateRanges {
				host := cidr
				separator := strings.IndexByte(cidr, '%')
				if separator >= 0 {
					host = cidr[:separator]
				}

				host = strings.TrimSpace(host)
				expr := host
				prefix, convErr := CIDRExpressionToPrefix(expr)
				if convErr != nil {
					convMsg := convErr.Error()
					return d.Err(convMsg)
				}
				if !prefix.IsValid() {
